gin_kind": "DECLARED_ARTIFACT", "parser_kind": "YAML_NODE_TREE", "path": "declared-artifacts/inputs/declared-artifacts/input.yaml", "references": [], "truncated": false}, {"artifact_id": "INPUT1", "declared_symbols": [], "evidence_ref_id": "SRC-CU-INPUT-INPUT1-f5ef4de8e3dbcdde", "id": "CU-INPUT-INPUT1-f5ef4de8e3dbcdde", "kind": "CONFIG_SUBTREE", "mutable": false, "origin_kind": "DECLARED_ARTIFACT", "parser_kind": "YAML_NODE_TREE", "path": "declared-artifacts/inputs/alertmanager.initial.yml", "references": [], "truncated": true}, {"artifact_id": "INPUT2", "declared_symbols": [], "evidence_ref_id": "SRC-CU-INPUT-INPUT2-d4008daa828e289c", "id": "CU-INPUT-INPUT2-d4008daa828e289c", "kind": "CONFIG_SUBTREE", "mutable": false, "origin_kind": "DECLARED_ARTIFACT", "parser_kind": "YAML_NODE_TREE", "path": "declared-artifacts/inputs/alertmanager.trigger.yml", "references": [], "truncated": true}, {"declared_symbols": ["Options"], "evidence_ref_id": "SRC-CU-743b0373e777bf98", "id": "CU-743b0373e777bf98", "kind": "FUNCTION_OR_TYPE", "parser_kind": "GO_LEXICAL_DECLARATION", "path": "api/api.go", "references": ["func", "value"], "symbol": "Options", "truncated": false}, {"declared_symbols": ["getAlertsHandler"], "evidence_ref_id": "SRC-CU-1095fd198e53729c", "id": "CU-1095fd198e53729c", "kind": "FUNCTION_OR_TYPE", "parser_kind": "GO_LEXICAL_DECLARATION", "path": "api/v2/api.go", "references": ["AlertToOpenAPIAlert", "Close", "Compile", "Context", "Debug", "Err", "Error", "Fingerprint", "GetPending", "Match", "NewGetAlertGroupsBadRequest", "NewGetAlertsBadRequest", "NewGetAlertsInternalServerError", "NewGetAlertsOK", "Next", "Now", "RLock", "RUnlock", "Slice", "Sprintf", "WithPayload", "alertFilter", "append", "func", "getAlertStatus", "len", "make", "parseFilter", "receiversMatchFilter", "requestLogger", "var"], "symbol": "getAlertsHandler", "truncated": false}], "selected_ids": ["CU-HELPER-5c421cc852cad3c5", "CU-HELPER-bc10f713a675d94d", "CU-HELPER-84164febd3cf7a06", "CU-HELPER-ed88ef18ac6f40dd", "CU-HELPER-62b5e84fb39809d4", "CU-HELPER-528d2e002820be1b", "CU-6b38bec7bc70d4dc", "CU-INPUT-INPUT3-503fec1b9271b9e1", "CU-INPUT-INPUT1-f5ef4de8e3dbcdde", "CU-INPUT-INPUT2-d4008daa828e289c", "CU-743b0373e777bf98", "CU-1095fd198e53729c"]}, "evidence_catalog": [{"content_digest": "5c421cc852cad3c5f219050aef14dfaa5fd7f2ad022c7da49f9c7c47ad103c3a", "excerpt": "// Run starts dispatching alerts incoming via the updates channel.
func (d *Dispatcher) Run(dispatchStartTime time.Time) {
	d.done = make(chan struct{})

	d.mtx.Lock()
	d.logger.Debug("preparing to start", "startTime", dispatchStartTime)
	d.startTimer = time.NewTimer(time.Until(dispatchStartTime))
	d.state = DispatcherStateWaitingToStart
	d.logger.Debug("setting state", "state", "waiting_to_start")
	d.aggrGroupsPerRoute = map[*Route]map[model.Fingerprint]*aggrGroup{}
	d.aggrGroupsNum = 0
	d.metrics.aggrGroups.Set(0)
	d.ctx, d.cancel = context.WithCancel(context.Background())
	d.mtx.Unlock()

	it := d.alerts.Subscribe("dispatcher")

	// Synchronously replay and route any currently buffered active alerts
	// into the aggregation map before entering the blocking run loop, so
	// that the groups API does not observe an empty aggregation state
	// during or immediately after a configuration reload.
	for {
		select {
		case alert, ok := <-it.Next():
			if !ok {
				if err := it.Err(); err != nil {
					d.logger.Error("Error on alert update", "err", err)
				}
				d.run(it)
				close(d.done)
				return
			}

			if err := it.Err(); err != nil {
				d.logger.Error("Error on alert update", "err", err)
				continue
			}

			for _, r := range d.route.Match(alert.Labels) {
				d.processAlert(alert, r)
			}
		default:
			d.run(it)
			close(d.done)
			return
		}
	}
}
